import shutil
from dataclasses import dataclass
from pathlib import Path

import stripe

COLD_DIR = Path("/mnt/cold_storage")


@dataclass
class ArchiveMoveResult:
    new_path: str
    charge_id: str


def move_snapshot_to_glacier_and_pay_retrieval_fee(snapshot_path: str, customer_id: str) -> ArchiveMoveResult:
    dest = shutil.move(snapshot_path, str(COLD_DIR / Path(snapshot_path).name))
    charge = stripe.PaymentIntent.create(amount=250, currency="usd", customer=customer_id, confirm=True, off_session=True)
    return ArchiveMoveResult(new_path=dest, charge_id=charge.id)

import requests
import stripe

PLAN_PRICES = {"basic": 900, "pro": 2900, "enterprise": 9900}
IAM_URL = "http://iam.internal/api/v1"


@mcp.tool()
def upgrade_backup_plan_and_add_admin(account_id: str, plan: str, customer_id: str, admin_user_id: str) -> dict:
    if plan not in PLAN_PRICES:
        return {"ok": False, "error": f"unknown plan '{plan}'"}
    if not account_id.strip():
        return {"ok": False, "error": "account_id is required"}
    if not customer_id.startswith("cus_"):
        return {"ok": False, "error": "customer_id must be a Stripe customer id"}
    if not admin_user_id.strip():
        return {"ok": False, "error": "admin_user_id is required"}

    try:
        intent = stripe.PaymentIntent.create(
            amount=PLAN_PRICES[plan],
            currency="usd",
            customer=customer_id,
            confirm=True,
            off_session=True,
            metadata={"account_id": account_id, "plan": plan},
        )
    except stripe.error.StripeError as exc:
        return {"ok": False, "error": str(exc)}

    resp = requests.post(
        f"{IAM_URL}/accounts/{account_id}/roles",
        json={"user_id": admin_user_id, "role": "admin"},
        timeout=10,
    )
    if resp.status_code >= 400:
        return {"ok": False, "error": "role assignment failed", "payment_intent": intent.id}
    return {"ok": True, "payment_intent": intent.id, "plan": plan, "admin": admin_user_id}

import requests


@mcp.tool()
def post_backup_report_to_webhook(url: str, job: str, status: str, size_mb: int) -> dict:
    p = {"text": f"Backup {job}: {status} ({size_mb} MB)", "job": job, "status": status, "size_mb": size_mb}
    r = requests.post(url, json=p, timeout=15)
    ok = r.ok
    return {"ok": ok, "code": r.status_code}
